"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[739],{1819:(e,s,a)=>{a.d(s,{A:()=>p});var o=a(3365),n=a(8197),t=a.n(n),i=a(1947),r=a(7981),u=a(4524),l=a(1455);function p(e){let{title:s,children:a}=e,{t:n}=(0,i.uU)();return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(r.A,{}),(0,o.jsx)(u.A,{}),(0,o.jsxs)("main",{id:"contenu",className:"wrap page-prose",children:[(0,o.jsxs)("nav",{className:"crumbs","aria-label":"Fil d'Ariane",children:[(0,o.jsx)(t(),{href:"/",children:n.navHome}),(0,o.jsx)("span",{children:"/"}),(0,o.jsx)("span",{"aria-current":"page",children:s})]}),a]}),(0,o.jsx)(l.A,{})]})}},8541:(e,s,a)=>{a.d(s,{V:()=>i,f:()=>t});let o={fr:{crumb:"\xc0 propos",title:"\xc0 propos de Sakura Shop",lead:"Sakura Shop habille vos moments \xe0 la maison : pyjamas, ensembles et v\xeatements d’int\xe9rieur choisis pour \xeatre aussi beaux que confortables, livr\xe9s partout en Alg\xe9rie.",sell:{h:"Ce que nous vendons",p:["Nous sommes sp\xe9cialis\xe9s dans le v\xeatement d’int\xe9rieur f\xe9minin : ensembles en coton respirant, pyjamas en satin, mod\xe8les boutonn\xe9s et coupes amples. Chaque mod\xe8le est s\xe9lectionn\xe9 pour une chose simple — pouvoir \xeatre port\xe9 bien apr\xe8s le r\xe9veil sans avoir envie de se changer.","Nos tailles vont du S au XXL, parce qu’un v\xeatement d’int\xe9rieur n’a d’int\xe9r\xeat que s’il tombe bien."]},work:{h:"Comment nous travaillons",cards:[{h:"Paiement \xe0 la livraison",p:"Vous ne payez qu’\xe0 r\xe9ception. Vous ouvrez le colis et v\xe9rifiez l’article avant de r\xe9gler le livreur."},{h:"58 wilayas couvertes",p:"Nous livrons dans toute l’Alg\xe9rie, \xe0 domicile ou au bureau de livraison, selon ce qui vous arrange."},{h:"Conseil sur WhatsApp",p:"Un doute sur une taille ou une mati\xe8re ? \xc9crivez-nous, nous r\xe9pondons avant que vous commandiez."}]},fabric:{h:"Nos mati\xe8res",p:["Nous travaillons principalement le coton et le satin. Le coton pour la respirabilit\xe9 et l’usage quotidien ; le satin pour le tomber et la douceur. Les descriptions produit pr\xe9cisent syst\xe9matiquement la mati\xe8re et la coupe, afin que vous sachiez ce que vous commandez."]},contact:{h:"Nous contacter",p1a:"Pour toute question sur un mod\xe8le, une taille ou une commande en cours, le plus rapide reste le t\xe9l\xe9phone ou WhatsApp au ",p1b:". Vous pouvez aussi nous \xe9crire \xe0 ",p1c:".",p2a:"Retrouvez \xe9galement nos nouveaut\xe9s sur ",p2b:"notre page Facebook"}},ar:{crumb:"من نحن",title:"عن Sakura Shop",lead:"يرافقك Sakura Shop في لحظاتك داخل البيت: بيجامات وأطقم وملابس منزلية مختارة لتكون جميلة ومريحة في آن واحد، مع توصيل إلى كامل الجزائر.",sell:{h:"ماذا نبيع",p:["نحن متخصّصون في الملابس المنزلية النسائية: أطقم من القطن الخفيف، بيجامات من الساتان، موديلات بأزرار وقصّات واسعة. كل موديل مختار لسبب بسيط — أن تستطيعي ارتداءه بعد الاستيقاظ بوقت طويل دون رغبة في تغييره.","مقاساتنا من S إلى XXL، لأن الملابس المنزلية لا معنى لها إن لم تكن على القياس."]},work:{h:"كيف نعمل",cards:[{h:"الدفع عند الاستلام",p:"لا تدفعين إلا عند الاستلام. تفتحين الطرد وتتحقّقين من القطعة قبل الدفع لعامل التوصيل."},{h:"58 ولاية مغطّاة",p:"نوصّل إلى كامل الجزائر، إلى المنزل أو إلى مكتب التوصيل، حسبما يناسبك."},{h:"استشارة عبر واتساب",p:"مترددة في المقاس أو القماش؟ راسلينا، نجيبك قبل أن تطلبي."}]},fabric:{h:"أقمشتنا",p:["نعتمد أساسًا على القطن والساتان. القطن لخفّته واستعماله اليومي، والساتان لانسيابه ونعومته. وصف كل منتج يذكر القماش والقصّة دائمًا، حتى تعرفي تمامًا ما تطلبينه."]},contact:{h:"اتصلي بنا",p1a:"لأي سؤال عن موديل أو مقاس أو طلب جارٍ، الأسرع هو الهاتف أو واتساب على ",p1b:". يمكنك أيضًا مراسلتنا على ",p1c:".",p2a:"تابعي جديدنا كذلك على ",p2b:"صفحتنا على فيسبوك"}}},n={fr:{crumb:"Conditions g\xe9n\xe9rales de vente",title:"Conditions g\xe9n\xe9rales de vente",lead:"Les pr\xe9sentes conditions r\xe9gissent les ventes r\xe9alis\xe9es sur le site Sakura Shop. En passant commande, vous en acceptez les termes.",updated:"Derni\xe8re mise \xe0 jour : septembre 2026.",clauses:[{h:"Identification du vendeur",p:["Le site Sakura Shop est exploit\xe9 sous le nom commercial Sakura Shop, \xe9tabli Rue Slimani Abed (pr\xe8s de b\xe2timent 11\xe8me), Oued Rhiou, Alg\xe9rie.","Pour toute question ou demande concernant une commande, vous pouvez nous contacter au 0554 33 23 42 ou par e-mail \xe0 contact@sakurashop.dz."]},{h:"Objet et champ d’application",p:["Les pr\xe9sentes conditions g\xe9n\xe9rales de vente d\xe9finissent les r\xe8gles applicables aux achats effectu\xe9s sur le site Sakura Shop.","Elles s’appliquent \xe0 toute commande pass\xe9e par un client pour l’achat de v\xeatements d’int\xe9rieur, pyjamas et autres produits propos\xe9s sur le site.","La validation d’une commande signifie que le client reconna\xeet avoir pris connaissance des pr\xe9sentes conditions et les accepter."]},{h:"Produits",p:["Les produits propos\xe9s sont des v\xeatements d’int\xe9rieur et pyjamas. Chaque fiche produit pr\xe9cise la mati\xe8re, la coupe et les tailles disponibles.","Les photographies sont les plus fid\xe8les possibles ; de l\xe9g\xe8res variations de teinte peuvent appara\xeetre selon l’\xe9cran utilis\xe9."]},{h:"Prix",p:["Les prix sont indiqu\xe9s en dinars alg\xe9riens (DA), toutes taxes comprises, hors frais de livraison.","Les frais de livraison sont calcul\xe9s s\xe9par\xe9ment selon votre wilaya et le mode de livraison choisi, et vous sont indiqu\xe9s avant la validation de la commande.","Sakura Shop se r\xe9serve le droit de modifier ses prix \xe0 tout moment. Les produits sont factur\xe9s au tarif en vigueur au moment de l’enregistrement de la commande."]},{h:"Disponibilit\xe9",p:["Nos offres sont valables dans la limite des stocks disponibles.","En cas d’indisponibilit\xe9 d’un article apr\xe8s commande, nous vous en informons dans les meilleurs d\xe9lais et vous proposons soit un mod\xe8le \xe9quivalent, soit l’annulation sans frais de la commande."]},{h:"Commande",p:["La commande est enregistr\xe9e lorsque vous validez le formulaire avec vos coordonn\xe9es de livraison.","Un membre de notre \xe9quipe vous contacte ensuite par t\xe9l\xe9phone ou WhatsApp pour confirmer la commande, la taille et l’adresse avant exp\xe9dition.","Sakura Shop se r\xe9serve le droit d’annuler toute commande dont les coordonn\xe9es seraient manifestement erron\xe9es ou injoignables apr\xe8s plusieurs tentatives de contact."]},{h:"Paiement",p:["Le r\xe8glement s’effectue en esp\xe8ces, \xe0 la livraison, directement aupr\xe8s du livreur.","Vous pouvez ouvrir le colis et v\xe9rifier l’article avant de payer."]},{h:"Livraison",p:["Nous livrons dans les 58 wilayas d’Alg\xe9rie, \xe0 domicile ou au bureau du transporteur selon votre choix.","Les d\xe9lais indiqu\xe9s sur le site sont estimatifs et d\xe9pendent de votre wilaya ainsi que du transporteur.","Les d\xe9lais courent \xe0 compter de la confirmation de la commande.","En cas de retard ou de difficult\xe9 de livraison, nous vous invitons \xe0 contacter Sakura Shop afin que nous puissions suivre la situation avec le transporteur.","Cette disposition s’applique sans pr\xe9judice des droits et recours pr\xe9vus par la l\xe9gislation applicable."]},{h:"R\xe9ception de la commande",p:["Lors de la r\xe9ception du colis, nous vous recommandons de v\xe9rifier que le produit re\xe7u correspond bien \xe0 votre commande et de contr\xf4ler son \xe9tat.","En cas de probl\xe8me concernant le produit re\xe7u, notamment en cas d’erreur de mod\xe8le, de taille, de couleur ou de d\xe9faut apparent, veuillez contacter Sakura Shop dans les meilleurs d\xe9lais afin que nous puissions examiner votre demande.","Lorsque cela est possible, nous vous invitons \xe0 conserver l’emballage et le produit dans son \xe9tat initial jusqu’\xe0 la r\xe9solution de la r\xe9clamation."]},{h:"Retour et produit d\xe9fectueux ou non conforme",p:["Si le produit re\xe7u est d\xe9fectueux, endommag\xe9 ou ne correspond pas au produit command\xe9, veuillez contacter Sakura Shop afin de nous signaler le probl\xe8me et de nous fournir les informations n\xe9cessaires \xe0 son traitement.","Apr\xe8s examen de la situation, Sakura Shop pourra proposer, selon le cas et les dispositions applicables, une nouvelle livraison conforme, un \xe9change ou l’annulation de la commande avec remboursement.","Pour faciliter le traitement de la demande, des photographies du produit concern\xe9 peuvent \xeatre demand\xe9es.","Les droits du client pr\xe9vus par la l\xe9gislation applicable restent pleinement applicables."]},{h:"R\xe9clamations et service client",p:["Toute r\xe9clamation relative \xe0 une commande, \xe0 un produit ou \xe0 une livraison peut \xeatre adress\xe9e \xe0 notre service client par t\xe9l\xe9phone au 0554 33 23 42, par WhatsApp ou par e-mail \xe0 contact@sakurashop.dz.","Afin de nous permettre de traiter rapidement votre demande, nous vous invitons \xe0 communiquer votre nom, votre num\xe9ro de t\xe9l\xe9phone ainsi que, lorsque cela est disponible, la r\xe9f\xe9rence de votre commande.","Notre \xe9quipe examine chaque r\xe9clamation et vous indique les d\xe9marches \xe0 suivre selon la nature du probl\xe8me."]},{h:"Donn\xe9es personnelles",p:["Les informations que vous nous communiquez (nom, t\xe9l\xe9phone, adresse) sont utilis\xe9es uniquement pour traiter et livrer votre commande, et pour vous contacter \xe0 son sujet.","Elles ne sont ni vendues ni c\xe9d\xe9es \xe0 des tiers, \xe0 l’exception du transporteur charg\xe9 de la livraison, qui en a besoin pour vous remettre le colis.","Vous pouvez demander la consultation, la rectification ou la suppression de vos donn\xe9es en nous \xe9crivant \xe0 contact@sakurashop.dz."]},{h:"Responsabilit\xe9",p:["Sakura Shop s’engage \xe0 pr\xe9senter les produits et leurs caract\xe9ristiques de mani\xe8re aussi fid\xe8le que possible. De l\xe9g\xe8res diff\xe9rences de couleur peuvent toutefois appara\xeetre selon l’\xe9cran ou les param\xe8tres d’affichage utilis\xe9s.","Sakura Shop ne peut \xeatre tenue responsable des difficult\xe9s ou retards r\xe9sultant de circonstances ind\xe9pendantes de sa volont\xe9, notamment certains incidents affectant le transporteur, les conditions m\xe9t\xe9orologiques ou tout autre \xe9v\xe9nement ext\xe9rieur emp\xeachant ou perturbant la livraison.","Cette disposition ne limite pas les droits et recours qui peuvent \xeatre pr\xe9vus par les dispositions l\xe9gales applicables."]},{h:"Modification des CGV",p:["Sakura Shop se r\xe9serve la possibilit\xe9 de modifier les pr\xe9sentes conditions g\xe9n\xe9rales de vente afin de les adapter \xe0 l’\xe9volution de ses services, de son activit\xe9 ou de la r\xe9glementation applicable.","Les conditions g\xe9n\xe9rales applicables \xe0 une commande sont celles qui sont accept\xe9es par le client au moment de la validation de cette commande.","Les modifications apport\xe9es apr\xe8s la validation d’une commande ne s’appliquent pas \xe0 cette commande."]},{h:"Droit applicable et r\xe8glement des litiges",p:["Les pr\xe9sentes conditions g\xe9n\xe9rales de vente sont soumises au droit alg\xe9rien.","En cas de difficult\xe9 ou de litige concernant une commande, le client est invit\xe9 \xe0 contacter Sakura Shop en priorit\xe9 afin de rechercher une solution amiable.","Les r\xe9clamations sont examin\xe9es de bonne foi et Sakura Shop s’efforce d’apporter une r\xe9ponse dans les meilleurs d\xe9lais.","\xc0 d\xe9faut de r\xe9solution amiable, le litige pourra \xeatre soumis aux autorit\xe9s ou juridictions comp\xe9tentes conform\xe9ment \xe0 la l\xe9gislation alg\xe9rienne applicable."]},{h:"Contact",p:["Pour toute question relative \xe0 ces conditions ou \xe0 une commande : 0554 33 23 42 ou contact@sakurashop.dz."]}]},ar:{crumb:"الشروط العامة للبيع",title:"الشروط العامة للبيع",lead:"تنظّم هذه الشروط عمليات البيع التي تتم عبر موقع Sakura Shop. بتقديمك للطلب فإنك توافقين على بنودها.",updated:"آخر تحديث: سبتمبر 2026.",clauses:[{h:"بيانات البائع",p:["يُدار موقع Sakura Shop تحت الاسم التجاري Sakura Shop، ومقرّه بشارع سليماني عبد (قرب العمارة 11)، وادي رهيو، الجزائر.","لأي سؤال أو طلب يتعلق بالطلبية، يمكنك التواصل معنا على الرقم 0554 33 23 42 أو عبر البريد الإلكتروني contact@sakurashop.dz."]},{h:"موضوع الشروط ونطاق تطبيقها",p:["تحدد هذه الشروط العامة للبيع القواعد المطبقة على عمليات الشراء التي تتم عبر موقع Sakura Shop.","تنطبق هذه الشروط على كل طلبية يقوم بها العميل لشراء الملابس المنزلية والبيجامات وغيرها من المنتجات المعروضة على الموقع.","يعني تأكيد الطلب أن العميل قد اطّلع على هذه الشروط ووافق عليها."]},{h:"المنتجات",p:["المنتجات المعروضة هي ملابس منزلية وبيجامات. تذكر بطاقة كل منتج القماش والقصّة والمقاسات المتوفرة.","الصور مطابقة قدر الإمكان للمنتجات، وقد تظهر فروق طفيفة في اللون حسب الشاشة أو إعدادات العرض المستخدمة."]},{h:"الأسعار",p:["الأسعار معروضة بالدينار الجزائري (دج)، شاملة للرسوم، دون تكاليف التوصيل.","تُحسب تكاليف التوصيل بشكل منفصل حسب ولايتك وطريقة التوصيل المختارة، وتُعرض عليك قبل تأكيد الطلب.","يحتفظ Sakura Shop بحق تعديل أسعاره في أي وقت. تُحتسب قيمة المنتجات بالسعر الساري وقت تسجيل الطلب."]},{h:"التوفّر",p:["عروضنا سارية في حدود المخزون المتوفر.","في حال عدم توفر منتج بعد تقديم الطلب، نُعلمك في أقرب وقت ممكن ونقترح عليك إما منتجًا مماثلًا أو إلغاء الطلب دون مصاريف."]},{h:"الطلب",p:["يُسجَّل الطلب عند تأكيدك للاستمارة ببيانات التوصيل الخاصة بك.","يتصل بك بعدها أحد أفراد فريقنا هاتفيًا أو عبر واتساب لتأكيد الطلب والمقاس والعنوان قبل الإرسال.","يحتفظ Sakura Shop بحق إلغاء أي طلب تكون بياناته خاطئة بشكل واضح أو يتعذّر الاتصال بصاحبه بعد عدة محاولات."]},{h:"الدفع",p:["يتم الدفع نقدًا عند الاستلام، مباشرةً لعامل التوصيل.","يمكنك فتح الطرد والتحقّق من القطعة قبل الدفع."]},{h:"التوصيل",p:["نوصّل إلى 58 ولاية عبر الجزائر، إلى المنزل أو إلى مكتب الناقل حسب اختيارك.","المدد المعروضة على الموقع تقديرية وتتعلق بولايتك وبالناقل.","تبدأ مدة التوصيل من تاريخ تأكيد الطلب.","في حال حدوث تأخر أو صعوبة في التوصيل، ندعوك للتواصل مع Sakura Shop حتى نتمكن من متابعة الوضع مع شركة التوصيل.","يُطبّق هذا دون المساس بالحقوق ووسائل الانتصاف المنصوص عليها في التشريع المعمول به."]},{h:"استلام الطلب",p:["عند استلام الطرد، ننصحك بالتأكد من أن المنتج المستلم يطابق طلبك والتحقق من حالته.","في حال وجود مشكلة في المنتج المستلم، مثل خطأ في الموديل أو المقاس أو اللون أو وجود عيب ظاهر، يُرجى التواصل مع Sakura Shop في أقرب وقت حتى نتمكن من دراسة طلبك.","عندما يكون ذلك ممكنًا، ننصحك بالاحتفاظ بالتغليف والمنتج في حالته الأصلية إلى حين معالجة الشكوى."]},{h:"إرجاع المنتج والمنتج المعيب أو غير المطابق",p:["إذا كان المنتج المستلم معيبًا أو متضررًا أو لا يطابق المنتج المطلوب، يُرجى التواصل مع Sakura Shop للإبلاغ عن المشكلة وتزويدنا بالمعلومات اللازمة لمعالجتها.","بعد دراسة الحالة، يمكن لـ Sakura Shop، حسب الحالة والأحكام المعمول بها، اقتراح إرسال منتج مطابق من جديد أو استبداله أو إلغاء الطلب مع رد المبلغ.","لتسهيل معالجة الطلب، قد يُطلب منك إرسال صور للمنتج المعني.","تبقى حقوق العميل المنصوص عليها في التشريع المعمول به سارية بالكامل."]},{h:"الشكاوى وخدمة العملاء",p:["يمكن تقديم أي شكوى تتعلق بطلب أو منتج أو توصيل إلى خدمة العملاء عبر الهاتف على الرقم 0554 33 23 42 أو عبر واتساب أو البريد الإلكتروني contact@sakurashop.dz.","لتسهيل معالجة طلبك بسرعة، نرجو تزويدنا باسمك ورقم هاتفك، وكذلك رقم الطلب إن كان متوفرًا.","يقوم فريقنا بدراسة كل شكوى وإبلاغك بالإجراءات المناسبة حسب طبيعة المشكلة."]},{h:"المعطيات الشخصية",p:["المعلومات التي تزوّديننا بها (الاسم، الهاتف، العنوان) تُستعمل فقط لمعالجة طلبك وتوصيله وللاتصال بك بشأنه.","لا تُباع هذه المعلومات ولا تُمنح لأطراف أخرى، باستثناء الناقل المكلّف بالتوصيل الذي يحتاجها لتسليمك الطرد.","يمكنك طلب الاطلاع على معطياتك أو تصحيحها أو حذفها بمراسلتنا على contact@sakurashop.dz."]},{h:"المسؤولية",p:["يلتزم Sakura Shop بعرض المنتجات وخصائصها بأكبر قدر ممكن من الدقة. ومع ذلك، قد تظهر فروق طفيفة في اللون حسب الشاشة أو إعدادات العرض المستخدمة.","لا يتحمل Sakura Shop مسؤولية الصعوبات أو التأخيرات الناتجة عن ظروف خارجة عن إرادته، بما في ذلك بعض الحوادث التي تؤثر على شركة التوصيل أو الظروف الجوية أو أي حدث خارجي آخر يمنع أو يعطل عملية التوصيل.","لا يحد هذا البند من الحقوق ووسائل الانتصاف التي قد ينص عليها التشريع المعمول به."]},{h:"تعديل الشروط العامة للبيع",p:["يحتفظ Sakura Shop بإمكانية تعديل هذه الشروط العامة للبيع من أجل تكييفها مع تطور خدماته أو نشاطه أو التشريعات المعمول بها.","تكون الشروط العامة المطبقة على أي طلب هي الشروط التي وافق عليها العميل وقت تأكيد الطلب.","لا تسري التعديلات التي تتم بعد تأكيد الطلب بأثر رجعي على ذلك الطلب."]},{h:"القانون المطبق وتسوية النزاعات",p:["تخضع هذه الشروط العامة للبيع للقانون الجزائري.","في حال حدوث صعوبة أو نزاع يتعلق بطلب ما، يُدعى العميل إلى التواصل مع Sakura Shop أولاً من أجل محاولة إيجاد حل ودي.","تتم دراسة الشكاوى بحسن نية، ويسعى Sakura Shop إلى تقديم رد في أقرب وقت ممكن.","في حال عدم التوصل إلى حل ودي، يمكن عرض النزاع على الجهات أو المحاكم المختصة وفقًا للتشريع الجزائري المعمول به."]},{h:"الاتصال",p:["لأي سؤال يتعلق بهذه الشروط أو بطلب ما: 0554 33 23 42 أو contact@sakurashop.dz."]}]}},t=e=>o[e],i=e=>n[e]}}]);